#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct PpcInputSnapshot {
    pub key_map: [u8; 16],
    pub mouse_button: bool,
    pub mouse_v: i16,
    pub mouse_h: i16,
}

impl PpcInputSnapshot {
    fn key_down(&self, key_code: u8) -> bool {
        if key_code >= 128 {
            return false;
        }
        let idx = (key_code / 8) as usize;
        let bit = 1u8 << (key_code % 8);
        self.key_map[idx] & bit != 0
    }

    fn any_key_down(&self, key_codes: &[u8]) -> bool {
        key_codes.iter().copied().any(|key| self.key_down(key))
    }

    fn is_idle(&self) -> bool {
        !self.mouse_button && self.key_map.iter().all(|byte| *byte == 0)
    }
}

