#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PpcQuickDrawSurface {
    front_buffer: PpcFrontBuffer,
    top: i16,
    left: i16,
    ctable_handle: Option<u32>,
}

impl PpcQuickDrawSurface {
    fn local_point(self, (h, v): (i32, i32)) -> (i32, i32) {
        (h - i32::from(self.left), v - i32::from(self.top))
    }

    fn local_rect(self, (top, left, bottom, right): (i16, i16, i16, i16)) -> (i32, i32, i32, i32) {
        (
            i32::from(top) - i32::from(self.top),
            i32::from(left) - i32::from(self.left),
            i32::from(bottom) - i32::from(self.top),
            i32::from(right) - i32::from(self.left),
        )
    }

    fn local_rect_i16(
        self,
        (top, left, bottom, right): (i16, i16, i16, i16),
    ) -> (i16, i16, i16, i16) {
        (
            top.wrapping_sub(self.top),
            left.wrapping_sub(self.left),
            bottom.wrapping_sub(self.top),
            right.wrapping_sub(self.left),
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PpcQ3ViewportRect {
    left: u32,
    top: u32,
    right: u32,
    bottom: u32,
}

impl PpcQ3ViewportRect {
    fn full(front_buffer: PpcFrontBuffer) -> Self {
        Self {
            left: 0,
            top: 0,
            right: front_buffer.width,
            bottom: front_buffer.height,
        }
    }

    fn from_q3_area(
        front_buffer: PpcFrontBuffer,
        min_x: f32,
        min_y: f32,
        max_x: f32,
        max_y: f32,
    ) -> Option<Self> {
        if !min_x.is_finite() || !min_y.is_finite() || !max_x.is_finite() || !max_y.is_finite() {
            return None;
        }
        if max_x <= min_x || max_y <= min_y {
            return None;
        }
        let width = front_buffer.width as f32;
        let height = front_buffer.height as f32;
        let left = min_x.floor().clamp(0.0, width) as u32;
        let right = max_x.ceil().clamp(0.0, width) as u32;
        let top = min_y.floor().clamp(0.0, height) as u32;
        let bottom = max_y.ceil().clamp(0.0, height) as u32;
        if right <= left || bottom <= top {
            return None;
        }
        Some(Self {
            left,
            top,
            right,
            bottom,
        })
    }

    fn inclusive_bounds(self) -> Option<(i32, i32, i32, i32)> {
        if self.right <= self.left || self.bottom <= self.top {
            return None;
        }
        Some((
            i32::try_from(self.left).ok()?,
            i32::try_from(self.top).ok()?,
            i32::try_from(self.right.checked_sub(1)?).ok()?,
            i32::try_from(self.bottom.checked_sub(1)?).ok()?,
        ))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PpcQ3SoftwareFrontBufferSurface {
    front_buffer: PpcFrontBuffer,
    span: Option<PpcSectionMemSpan>,
}

impl PpcQ3SoftwareFrontBufferSurface {
    fn new(memory: &mut PpcSectionMem, front_buffer: PpcFrontBuffer) -> Self {
        let span = ppc_q3_front_buffer_span_len(front_buffer)
            .and_then(|len| memory.writable_span(front_buffer.base_addr, len));
        Self { front_buffer, span }
    }

    fn read_pixel(self, memory: &mut PpcSectionMem, point: (i32, i32)) -> Option<u16> {
        if let (Some(span), Some(offset)) = (self.span, self.pixel_relative_offset(point)) {
            return memory.read_u16_be_in_span(span, offset);
        }
        ppc_q3_read_software_pixel(memory, self.front_buffer, point)
    }

    fn write_pixel(self, memory: &mut PpcSectionMem, point: (i32, i32), color: u16) -> bool {
        if let (Some(span), Some(offset)) = (self.span, self.pixel_relative_offset(point)) {
            return memory.write_u16_be_in_span(span, offset, color).is_some();
        }
        ppc_q3_write_software_pixel(memory, self.front_buffer, point, color)
    }

    fn pixel_relative_offset(self, point: (i32, i32)) -> Option<usize> {
        ppc_q3_front_buffer_pixel_relative_offset(self.front_buffer, point)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
