                && memory.write_u32_be(switch_info + 2, 0x80).is_some()
                && memory.write_u16_be(switch_info + 6, 0).is_some()
                && memory.write_u32_be(switch_info + 8, base_addr).is_some()
                && memory.write_u32_be(switch_info + 12, 0).is_some()
