fn ppc_q3_matrix4x4_set_rotate_xyz(
    memory: &mut PpcSectionMem,
    matrix_ptr: u32,
    x_angle: f32,
    y_angle: f32,
    z_angle: f32,
) -> u32 {
    let matrix = ppc_q3_matrix4x4_multiply_values(
        ppc_q3_matrix4x4_multiply_values(
            ppc_q3_matrix4x4_rotate_x(x_angle),
            ppc_q3_matrix4x4_rotate_y(y_angle),
        ),
        ppc_q3_matrix4x4_rotate_z(z_angle),
    );
    if ppc_write_q3_matrix4x4(memory, matrix_ptr, &matrix).is_some() {
        matrix_ptr
    } else {
        0
    }
}

fn ppc_q3_matrix4x4_multiply(
    memory: &mut PpcSectionMem,
    left_ptr: u32,
    right_ptr: u32,
    result_ptr: u32,
) -> u32 {
    let Some(left) = ppc_read_q3_matrix4x4(memory, left_ptr) else {
        return 0;
    };
    let Some(right) = ppc_read_q3_matrix4x4(memory, right_ptr) else {
        return 0;
    };
    let result = ppc_q3_matrix4x4_multiply_values(left, right);
    if ppc_write_q3_matrix4x4(memory, result_ptr, &result).is_some() {
        result_ptr
    } else {
        0
    }
}

fn ppc_write_microseconds(cpu: &PpcCpu, memory: &mut PpcSectionMem, tick_count: u32) {
    ppc_write_microseconds_value(
        cpu,
        memory,
        u64::from(tick_count).saturating_mul(PPC_MICROSECONDS_PER_TICK),
    );
}

fn ppc_write_microseconds_value(cpu: &PpcCpu, memory: &mut PpcSectionMem, usecs: u64) {
    let microseconds_ptr = cpu.gpr[3];
    if microseconds_ptr == 0 || !ppc_memory_can_write_bytes(memory, microseconds_ptr, 8) {
        return;
    }
    let _ = memory.write_u32_be(microseconds_ptr, (usecs >> 32) as u32);
    let _ = memory.write_u32_be(microseconds_ptr + 4, usecs as u32);
}

fn ppc_seconds_to_date(memory: &mut PpcSectionMem, seconds: u32, date_ptr: u32) {
    if date_ptr == 0 || !ppc_memory_can_write_bytes(memory, date_ptr, 14) {
        return;
    }

    let mut remaining_days = seconds / 86_400;
    let seconds_today = seconds % 86_400;
    let mut year = 1904u16;
    loop {
        let days_this_year = if ppc_is_gregorian_leap_year(year) {
            366
        } else {
            365
        };
        if remaining_days < days_this_year {
            break;
        }
        remaining_days -= days_this_year;
        year += 1;
    }

    let mut month = 1u16;
    loop {
        let days_this_month = ppc_days_in_gregorian_month(year, month);
        if remaining_days < days_this_month {
            break;
        }
        remaining_days -= days_this_month;
        month += 1;
    }

    let days_since_epoch = seconds / 86_400;
    let fields = [
        year,
        month,
        remaining_days as u16 + 1,
        (seconds_today / 3_600) as u16,
        ((seconds_today % 3_600) / 60) as u16,
        (seconds_today % 60) as u16,
        ((days_since_epoch + 5) % 7) as u16 + 1,
    ];

    // Inside Macintosh: Operating System Utilities (1994), pp. 4-23–4-25 and 4-38:
    // SecondsToDate converts seconds since 1904-01-01 into the seven signed,
    // big-endian DateTimeRec fields, with Sunday numbered 1 through Saturday 7.
    for (index, field) in fields.into_iter().enumerate() {
        let _ = memory.write_u16_be(date_ptr + index as u32 * 2, field);
    }
}

fn ppc_is_gregorian_leap_year(year: u16) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

fn ppc_days_in_gregorian_month(year: u16, month: u16) -> u32 {
    match month {
        2 if ppc_is_gregorian_leap_year(year) => 29,
        2 => 28,
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    }
}

fn ppc_math_dtox80(cpu: &PpcCpu, memory: &mut PpcSectionMem) -> bool {
    let Some(hi) = memory.read_u32_be(cpu.gpr[3]) else {
        return false;
    };
    let Some(lo) = memory.read_u32_be(cpu.gpr[3].wrapping_add(4)) else {
        return false;
    };
    let extended = Extended80::from(f64::from_bits((u64::from(hi) << 32) | u64::from(lo)));
    let sign_bit = if extended.sign { 0x8000 } else { 0 };
    let out = cpu.gpr[4];

    // Universal Interfaces fp.h (MathLib 2), `dtox80(const double *, extended80 *)`:
    // convert a PowerPC double into the 10-byte big-endian 68K extended format.
    memory
        .write_u16_be(out, sign_bit | extended.exponent)
        .is_some()
        && memory
            .write_u16_be(out.wrapping_add(2), (extended.significand >> 48) as u16)
            .is_some()
        && memory
            .write_u16_be(out.wrapping_add(4), (extended.significand >> 32) as u16)
            .is_some()
        && memory
            .write_u16_be(out.wrapping_add(6), (extended.significand >> 16) as u16)
            .is_some()
        && memory
            .write_u16_be(out.wrapping_add(8), extended.significand as u16)
            .is_some()
}

fn ppc_virtual_microseconds(
    tick_count: u32,
    cycles_per_tick: u32,
    cycle_phase: u32,
    elapsed_cycles: u64,
) -> u64 {
    let cycles_per_tick = u64::from(cycles_per_tick.max(1));
    let elapsed_cycles = u64::from(cycle_phase).saturating_add(elapsed_cycles);
    u64::from(tick_count)
        .saturating_mul(PPC_MICROSECONDS_PER_TICK)
        .saturating_add(elapsed_cycles.saturating_mul(PPC_MICROSECONDS_PER_TICK) / cycles_per_tick)
}

fn ppc_virtual_tick_count(
    tick_count: u32,
    cycles_per_tick: u32,
    cycle_phase: u32,
    elapsed_cycles: u64,
) -> u32 {
    // Inside Macintosh: Processes (1993), p. 3-46: TickCount is the low-memory
    // time counter maintained by the vertical retrace interrupt. The native
    // runner keeps the persisted counter at the start of an execution slice,
    // so imports within that slice must include elapsed guest cycles. This is
    // especially important when an idle poll is accelerated with extra cycles:
    // inventing a caller-local future tick can make two Toolbox clock reads
    // disagree and send applications down their fatal startup path.
    let cycles_per_tick = u64::from(cycles_per_tick.max(1));
    let elapsed_cycles = u64::from(cycle_phase).saturating_add(elapsed_cycles);
    tick_count.wrapping_add((elapsed_cycles / cycles_per_tick) as u32)
}

fn dispatch_simple_hot_import_fast(
    target: &PpcImportDispatcherTarget,
    cpu: &mut PpcCpu,
    memory: &mut PpcSectionMem,
    microseconds: u64,
) -> Option<PpcImportAction> {
    match target {
        PpcImportDispatcherTarget::Microseconds => {
            ppc_write_microseconds_value(cpu, memory, microseconds);
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathSqrt => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.sqrt().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathSin => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.sin().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathCos => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.cos().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathAsin => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.asin().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathTan => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.tan().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathAtan => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.atan().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathAtan2 => {
            let y = f64::from_bits(cpu.fpr[1]);
            let x = f64::from_bits(cpu.fpr[2]);
            cpu.fpr[1] = y.atan2(x).to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathPow => {
            let base = f64::from_bits(cpu.fpr[1]);
            let exponent = f64::from_bits(cpu.fpr[2]);
            cpu.fpr[1] = base.powf(exponent).to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathLog => {
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.ln().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        PpcImportDispatcherTarget::MathLog10 => {
            // Inside Macintosh: PowerPC Numerics (1994), pp. 10-23–10-24.
            let value = f64::from_bits(cpu.fpr[1]);
            cpu.fpr[1] = value.log10().to_bits();
            Some(PpcImportAction::ReturnPreserve)
        }
        _ => None,
    }
}

fn dispatch_q3_submit_import_fast(
    target: &PpcImportDispatcherTarget,
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
    q3_objects: &[PpcQ3ObjectRecord],
    q3_group_memberships: &[PpcQ3GroupMembershipRecord],
    q3_views: &mut Vec<PpcQ3ViewStateRecord>,
    q3_view_transforms: &mut Vec<PpcQ3ViewTransformRecord>,
    q3_submissions: &mut Vec<PpcQ3SubmissionRecord>,
    q3_submission_transforms: &mut Vec<PpcQ3SubmissionTransformRecord>,
    q3_view_materials: &mut Vec<PpcQ3ViewMaterialRecord>,
    q3_submission_materials: &mut Vec<PpcQ3SubmissionMaterialRecord>,
    q3_submission_lights: &mut Vec<PpcQ3SubmissionLightRecord>,
    q3_view_state_stack: &mut Vec<PpcQ3ViewStateSnapshotRecord>,
    q3_attributes: &[PpcQ3AttributeRecord],
    q3_styles: &[PpcQ3StyleRecord],
    q3_shader_boundaries: &[PpcQ3ShaderBoundaryRecord],
    q3_shader_uv_transforms: &[PpcQ3ShaderUvTransformRecord],
    q3_texture_shaders: &[PpcQ3TextureShaderRecord],
    q3_mipmap_textures: &[PpcQ3MipmapTextureRecord],
    q3_trimeshes: &[PpcQ3TriMeshRecord],
    q3_fog_styles: &mut Vec<PpcQ3FogStyleRecord>,
    q3_lights: &[PpcQ3LightRecord],
    q3_error_state: &mut PpcQ3ErrorState,
) -> Option<PpcImportAction> {
    let kind = match target {
        PpcImportDispatcherTarget::Q3ShaderSubmit => PpcQ3SubmissionKind::Shader,
        PpcImportDispatcherTarget::Q3StyleSubmit => PpcQ3SubmissionKind::Style,
        PpcImportDispatcherTarget::Q3TriMeshSubmit => PpcQ3SubmissionKind::TriMesh,
        PpcImportDispatcherTarget::Q3ObjectSubmit => PpcQ3SubmissionKind::Object,
        PpcImportDispatcherTarget::Q3FogStyleSubmit => {
            return Some(PpcImportAction::Return(u32::from(ppc_q3_fog_style_submit(
                cpu,
                memory,
                q3_group_memberships,
                q3_views,
                q3_view_transforms,
                q3_submissions,
                q3_submission_transforms,
                q3_view_materials,
                q3_submission_materials,
                q3_fog_styles,
                q3_submission_lights,
                q3_shader_boundaries,
                q3_shader_uv_transforms,
                q3_texture_shaders,
                q3_mipmap_textures,
                q3_lights,
                q3_objects,
                q3_error_state,
            ))));
        }
        _ => return None,
    };
    Some(PpcImportAction::Return(u32::from(ppc_q3_submit(
        cpu,
        memory,
        q3_objects,
        q3_group_memberships,
        q3_views,
        q3_view_transforms,
        q3_submissions,
        q3_submission_transforms,
        q3_view_materials,
        q3_submission_materials,
        q3_submission_lights,
        q3_view_state_stack,
        q3_attributes,
        q3_styles,
        q3_shader_boundaries,
        q3_shader_uv_transforms,
        q3_texture_shaders,
        q3_mipmap_textures,
        q3_trimeshes,
        q3_lights,
        q3_error_state,
        kind,
    ))))
}

fn dispatch_q3_matrix_import_fast(
    target: &PpcImportDispatcherTarget,
    cpu: &PpcCpu,
    memory: &mut PpcSectionMem,
) -> Option<PpcImportAction> {
    match target {
        PpcImportDispatcherTarget::Q3Matrix3x3SetTranslate => {
            Some(PpcImportAction::Return(ppc_q3_matrix3x3_set_translate(
                memory,
                cpu.gpr[3],
                ppc_fpr_as_f32(cpu, 1),
                ppc_fpr_as_f32(cpu, 2),
            )))
        }
        PpcImportDispatcherTarget::Q3Matrix4x4SetIdentity => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_set_identity(memory, cpu.gpr[3]),
        )),
        PpcImportDispatcherTarget::Q3Matrix4x4SetTranslate => {
            Some(PpcImportAction::Return(ppc_q3_matrix4x4_set_translate(
                memory,
                cpu.gpr[3],
                ppc_fpr_as_f32(cpu, 1),
                ppc_fpr_as_f32(cpu, 2),
                ppc_fpr_as_f32(cpu, 3),
            )))
        }
        PpcImportDispatcherTarget::Q3Matrix4x4SetScale => {
            Some(PpcImportAction::Return(ppc_q3_matrix4x4_set_scale(
                memory,
                cpu.gpr[3],
                ppc_fpr_as_f32(cpu, 1),
                ppc_fpr_as_f32(cpu, 2),
                ppc_fpr_as_f32(cpu, 3),
            )))
        }
        PpcImportDispatcherTarget::Q3Matrix4x4SetRotateX => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_set_rotate_x(memory, cpu.gpr[3], ppc_fpr_as_f32(cpu, 1)),
        )),
        PpcImportDispatcherTarget::Q3Matrix4x4SetRotateY => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_set_rotate_y(memory, cpu.gpr[3], ppc_fpr_as_f32(cpu, 1)),
        )),
        PpcImportDispatcherTarget::Q3Matrix4x4SetRotateZ => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_set_rotate_z(memory, cpu.gpr[3], ppc_fpr_as_f32(cpu, 1)),
        )),
        PpcImportDispatcherTarget::Q3Matrix4x4SetRotateXyz => {
            Some(PpcImportAction::Return(ppc_q3_matrix4x4_set_rotate_xyz(
                memory,
                cpu.gpr[3],
                ppc_fpr_as_f32(cpu, 1),
                ppc_fpr_as_f32(cpu, 2),
                ppc_fpr_as_f32(cpu, 3),
            )))
        }
        PpcImportDispatcherTarget::Q3Matrix4x4Multiply => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_multiply(memory, cpu.gpr[3], cpu.gpr[4], cpu.gpr[5]),
        )),
        PpcImportDispatcherTarget::Q3Matrix4x4Transpose => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_transpose(memory, cpu.gpr[3], cpu.gpr[4]),
        )),
        PpcImportDispatcherTarget::Q3Matrix4x4Invert => Some(PpcImportAction::Return(
            ppc_q3_matrix4x4_invert(memory, cpu.gpr[3], cpu.gpr[4]),
        )),
        _ => None,
    }
}

