    #[test]
    fn hle_import_runner_handles_legacy_bit_utilities() {
        let mut set = load_pef_application(&synthetic_pef_with_import(b"BitSet")).unwrap();
        let byte = PPC_HEAP_BASE;
        set.memory.add_region(byte, vec![0; 2]);
        set.cpu.gpr[3] = byte;
        set.cpu.gpr[4] = 9;
        let set_probe = set.run_with_hle_imports(64);
        assert_eq!(set_probe.unsupported_import_index, None);
        assert_eq!(set.memory.read_u8(byte + 1), Some(0x40));

        let mut clear = load_pef_application(&synthetic_pef_with_import(b"BitClr")).unwrap();
        clear.memory.add_region(byte, vec![0xff; 2]);
        clear.cpu.gpr[3] = byte;
        clear.cpu.gpr[4] = 9;
        let clear_probe = clear.run_with_hle_imports(64);
        assert_eq!(clear_probe.unsupported_import_index, None);
        assert_eq!(clear.memory.read_u8(byte + 1), Some(0xbf));

        let mut not = load_pef_application(&synthetic_pef_with_import(b"BitNot")).unwrap();
        not.cpu.gpr[3] = 0x0f0f_55aa;
        let not_probe = not.run_with_hle_imports(64);
        assert_eq!(not_probe.unsupported_import_index, None);
        assert_eq!(not.cpu.gpr[3], 0xf0f0_aa55);
    }

    #[test]
    fn hle_import_runner_converts_fixed_to_extended_result_register() {
        let mut loaded = load_pef_application(&synthetic_pef_with_import(b"Fix2X")).unwrap();
        loaded.cpu.gpr[3] = (-98_304i32) as u32;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(f64::from_bits(loaded.cpu.fpr[1]), -1.5);
    }

    #[test]
    fn set_ptr_size_grows_only_a_terminal_nonrelocatable_block() {
        let mut memory = PpcSectionMem::new();
        let mut heap_cursor = PPC_HEAP_BASE;
        let heap_limit = PPC_HEAP_BASE + 0x1000;
        let mut ptrs = Vec::new();
        let mut free = Vec::new();
        let ptr = ppc_alloc_ptr(
            &mut memory,
            &mut heap_cursor,
            heap_limit,
            &mut ptrs,
            &mut free,
            8,
            true,
        );
        assert_ne!(ptr, 0);

        assert_eq!(
            ppc_set_ptr_size(
                &mut memory,
                &mut heap_cursor,
                heap_limit,
                &mut ptrs,
                ptr,
                24,
            ),
            PPC_NO_ERR
        );
        assert_eq!(ptrs[0].size, 24);
        assert_eq!(memory.read_u8(ptr + 23), Some(0));

        let second = ppc_alloc_ptr(
            &mut memory,
            &mut heap_cursor,
            heap_limit,
            &mut ptrs,
            &mut free,
            8,
            true,
        );
        assert_ne!(second, 0);
        assert_eq!(
            ppc_set_ptr_size(
                &mut memory,
                &mut heap_cursor,
                heap_limit,
                &mut ptrs,
                ptr,
                32,
            ),
            PPC_MEM_FULL_ERR
        );
        assert_eq!(ptrs[0].ptr, ptr);
        assert_eq!(ptrs[0].size, 24);
    }

    #[test]
    fn hle_import_runner_creates_and_links_a_classic_control_record() {
        let mut loaded = load_pef_application(&synthetic_pef_with_import(b"NewControl")).unwrap();
        let scratch = ppc_heap_alloc(
            &mut loaded.memory,
            &mut loaded.heap_cursor,
            loaded.heap_limit,
            64,
            true,
        );
        ppc_write_rect(&mut loaded.memory, scratch, 10, 20, 40, 140).unwrap();
        write_ppc_pstring(&mut loaded.memory, scratch + 8, b"Launch");
        let ref_con_slot =
            ppc_parameter_area_slot_addr(loaded.cpu.gpr[1], PPC_NATIVE_PARAMETER_GPR_COUNT)
                .unwrap();
        loaded
            .memory
            .write_u32_be(ref_con_slot, 0x1234_5678)
            .unwrap();
        loaded.cpu.gpr[3] = PPC_MAIN_GWORLD;
        loaded.cpu.gpr[4] = scratch;
        loaded.cpu.gpr[5] = scratch + 8;
        loaded.cpu.gpr[6] = 1;
        loaded.cpu.gpr[7] = 3;
        loaded.cpu.gpr[8] = 1;
        loaded.cpu.gpr[9] = 9;
        loaded.cpu.gpr[10] = 16;

        let probe = loaded.run_with_hle_imports(128);

        assert_eq!(probe.unsupported_import_index, None);
        let handle = loaded.cpu.gpr[3];
        let control = loaded.memory.read_u32_be(handle).unwrap();
        assert_ne!(handle, 0);
        assert_eq!(
            loaded
                .memory
                .read_u32_be(PPC_MAIN_GWORLD + PPC_CWINDOW_CONTROL_LIST_OFFSET),
            Some(handle)
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, control + PPC_CONTROL_RECT_OFFSET),
            Some((10, 20, 40, 140))
        );
        assert_eq!(
            loaded
                .memory
                .read_u32_be(control + PPC_CONTROL_OWNER_OFFSET),
            Some(PPC_MAIN_GWORLD)
        );
        assert_eq!(
            loaded
                .memory
                .read_u16_be(control + PPC_CONTROL_VALUE_OFFSET),
            Some(3)
        );
        assert_eq!(
            loaded.memory.read_u16_be(control + PPC_CONTROL_MIN_OFFSET),
            Some(1)
        );
        assert_eq!(
            loaded.memory.read_u16_be(control + PPC_CONTROL_MAX_OFFSET),
            Some(9)
        );
        assert_eq!(
            loaded
                .memory
                .read_u32_be(control + PPC_CONTROL_REF_CON_OFFSET),
            Some(0x1234_5678)
        );
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, control + PPC_CONTROL_TITLE_OFFSET),
            Some(b"Launch".to_vec())
        );
        assert_eq!(
            loaded.controls,
            vec![PpcControlRecord {
                handle,
                proc_id: 16
            }]
        );
    }

    #[test]
    fn classic_control_hit_testing_and_disposal_follow_the_window_list() {
        let mut loaded = load_pef_application(&synthetic_pef()).unwrap();
        let scratch = ppc_heap_alloc(
            &mut loaded.memory,
            &mut loaded.heap_cursor,
            loaded.heap_limit,
            32,
            true,
        );
        ppc_write_rect(&mut loaded.memory, scratch, 5, 6, 25, 86).unwrap();
        write_ppc_pstring(&mut loaded.memory, scratch + 8, b"OK");
        let handle = ppc_new_control_values(
            &mut loaded.memory,
            &mut loaded.heap_cursor,
            loaded.heap_limit,
            &mut loaded.last_mem_error,
            &mut loaded.handles,
            &mut loaded.controls,
            PPC_MAIN_GWORLD,
            scratch,
            scratch + 8,
            true,
            0,
            0,
            1,
            0,
            0,
        );
        assert_ne!(handle, 0);
        assert_eq!(
            ppc_find_control_at_point(
                &mut loaded.memory,
                &loaded.controls,
                PPC_MAIN_GWORLD,
                10,
                10,
            ),
            Some((handle, 10))
        );

        ppc_dispose_control(
            &mut loaded.memory,
            &mut loaded.handles,
            &mut loaded.free_handle_blocks,
            &mut loaded.controls,
            handle,
        );

        assert_eq!(loaded.memory.read_u32_be(handle), Some(0));
        assert_eq!(
            loaded
                .memory
                .read_u32_be(PPC_MAIN_GWORLD + PPC_CWINDOW_CONTROL_LIST_OFFSET),
            Some(0)
        );
        assert!(loaded.controls.is_empty());
    }

    #[test]
    fn hle_import_runner_creates_window_title_and_zoom_state() {
        let mut loaded = load_pef_application(&synthetic_pef_with_import(b"NewWindow")).unwrap();
        let scratch = ppc_heap_alloc(
            &mut loaded.memory,
            &mut loaded.heap_cursor,
            loaded.heap_limit,
            64,
            true,
        );
        ppc_write_rect(&mut loaded.memory, scratch, 40, 50, 240, 350).unwrap();
        write_ppc_pstring(&mut loaded.memory, scratch + 8, b"Document");
        loaded.cpu.gpr[3] = 0;
        loaded.cpu.gpr[4] = scratch;
        loaded.cpu.gpr[5] = scratch + 8;
        loaded.cpu.gpr[6] = 1;
        loaded.cpu.gpr[7] = 0;
        loaded.cpu.gpr[8] = u32::MAX;
        loaded.cpu.gpr[9] = 1;
        loaded.cpu.gpr[10] = 0x4455_6677;

        let probe = loaded.run_with_hle_imports(128);

        assert_eq!(probe.unsupported_import_index, None);
        let window = loaded.cpu.gpr[3];
        assert_ne!(window, 0);
        let title_handle = loaded
            .memory
            .read_u32_be(window + PPC_CWINDOW_TITLE_HANDLE_OFFSET)
            .unwrap();
        let title = loaded.memory.read_u32_be(title_handle).unwrap();
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, title),
            Some(b"Document".to_vec())
        );
        let state_handle = loaded
            .memory
            .read_u32_be(window + PPC_CWINDOW_STATE_HANDLE_OFFSET)
            .unwrap();
        let state = loaded.memory.read_u32_be(state_handle).unwrap();
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, state),
            Some((40, 50, 240, 350))
        );
        assert_eq!(
            ppc_read_rect(&mut loaded.memory, state + 8),
            Some((
                20,
                0,
                PPC_MAIN_SCREEN_HEIGHT as i16,
                PPC_MAIN_SCREEN_WIDTH as i16,
            ))
        );

        let mut zoom_cpu = loaded.cpu.clone();
        zoom_cpu.gpr[3] = window;
        zoom_cpu.gpr[4] = 8;
        ppc_zoom_window(&zoom_cpu, &mut loaded.memory, &mut loaded.gworlds);
        assert_eq!(
            ppc_dialog_global_bounds(&mut loaded.memory, &loaded.gworlds, window),
            Some((
                20,
                0,
                PPC_MAIN_SCREEN_HEIGHT as i16,
                PPC_MAIN_SCREEN_WIDTH as i16,
            ))
        );
    }

    #[test]
    fn window_resource_parameters_preserve_compiled_bounds_and_title() {
        let mut loaded = load_pef_application(&synthetic_pef()).unwrap();
        let mut wind = Vec::new();
        wind.extend_from_slice(&10i16.to_be_bytes());
        wind.extend_from_slice(&20i16.to_be_bytes());
        wind.extend_from_slice(&210i16.to_be_bytes());
        wind.extend_from_slice(&420i16.to_be_bytes());
        wind.extend_from_slice(&0u16.to_be_bytes());
        wind.extend_from_slice(&1u16.to_be_bytes());
        wind.extend_from_slice(&1u16.to_be_bytes());
        wind.extend_from_slice(&0x1234_5678u32.to_be_bytes());
        wind.push(4);
        wind.extend_from_slice(b"Game");

        let (bounds, title) = ppc_materialize_window_resource_parameters(
            &mut loaded.memory,
            &mut loaded.heap_cursor,
            loaded.heap_limit,
            &wind,
        )
        .unwrap();

        assert_eq!(
            ppc_read_rect(&mut loaded.memory, bounds),
            Some((10, 20, 210, 420))
        );
        assert_eq!(
            ppc_read_pstring_bytes(&mut loaded.memory, title),
            Some(b"Game".to_vec())
        );
    }

