        loaded.memory.write_u32_be(triangles_ptr, 0).unwrap();
        loaded.memory.write_u32_be(triangles_ptr + 4, 1).unwrap();
        loaded.memory.write_u32_be(triangles_ptr + 8, 2).unwrap();

