            ppc_heap_allocation_sequence_size(&[PPC_PIXMAP_SIZE, 4, 4, 10, 4, 10, 4, 10]).unwrap();
        loaded.cpu.gpr[3] = storage_ptr;
        loaded.cpu.gpr[4] = bounds_ptr;
