        assert_eq!(loaded.current_gworld, storage_ptr);
        assert_eq!(loaded.current_gdevice, PPC_MAIN_GDEVICE);
        assert_eq!(loaded.heap_cursor, heap_cursor + required);
        assert_eq!(loaded.gworlds.len(), gworld_count + 1);
