        loaded.cpu.gpr[4] = PPC_PREFERENCES_DIR_ID;
        loaded.cpu.gpr[5] = scratch;
        loaded.cpu.gpr[6] = created_dir_id_ptr;
        let second = loaded.run_with_hle_imports(64);

