    #[test]
    fn hle_import_runner_counts_uniques_and_updates_ppc_vfs_resources() {
        let pef = synthetic_pef_with_import(b"CountResources");
        let mut loaded = load_pef_application(&pef).unwrap();
        loaded.current_resource_refnum = 5;
        for (ref_num, res_id, handle) in [(5, 128, 0x1000), (7, 129, 0x1004), (5, 130, 0x1008)] {
            loaded.vfs_resources.push(PpcVfsResourceRecord {
                ref_num,
                path: String::new(),
                res_type: u32::from_be_bytes(*b"pref"),
                res_id,
                name: Vec::new(),
                data: Vec::new(),
                raw_data: None,
                raw_attrs: None,
                attrs: PPC_RES_CHANGED_ATTR,
                handle,
            });
        }
        loaded.vfs_resources.push(PpcVfsResourceRecord {
            ref_num: 5,
            path: String::new(),
            res_type: u32::from_be_bytes(*b"misc"),
            res_id: 128,
            name: Vec::new(),
            data: Vec::new(),
            raw_data: None,
            raw_attrs: None,
            attrs: PPC_RES_CHANGED_ATTR,
            handle: 0x100c,
        });
        loaded.cpu.gpr[3] = u32::from_be_bytes(*b"pref");

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 3);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::Count1Resources;
        loaded.cpu.gpr[3] = u32::from_be_bytes(*b"pref");

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 2);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::UniqueID;
        loaded.cpu.gpr[3] = u32::from_be_bytes(*b"pref");

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 131);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::Unique1ID;
        loaded.cpu.gpr[3] = u32::from_be_bytes(*b"pref");

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 129);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::UpdateResFile;
        loaded.cpu.gpr[3] = 5;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);
        assert_eq!(
            loaded
                .vfs_resources
                .iter()
                .find(|record| record.ref_num == 5 && record.res_id == 128)
                .unwrap()
                .attrs
                & PPC_RES_CHANGED_ATTR,
            0
        );
        assert_ne!(
            loaded
                .vfs_resources
                .iter()
                .find(|record| record.ref_num == 7)
                .unwrap()
                .attrs
                & PPC_RES_CHANGED_ATTR,
            0
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::UpdateResFile;
        loaded.cpu.gpr[3] = 99;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_RES_F_NOT_FOUND_ERR);
    }

    #[test]
    fn hle_import_runner_mutates_ppc_vfs_resource_metadata() {
        let pef = synthetic_pef_with_import(b"SetResInfo");
        let mut loaded = load_pef_application(&pef).unwrap();
        let scratch = PPC_DATA_BASE + 0x2200;
        let handle = scratch + 0x40;
        loaded.memory.add_region(scratch, vec![0; 0x100]);
        write_ppc_pstring(&mut loaded.memory, scratch, b"NewName");
        loaded.vfs_resources.push(PpcVfsResourceRecord {
            ref_num: 5,
            path: String::new(),
            res_type: u32::from_be_bytes(*b"pref"),
            res_id: 100,
            name: b"OldName".to_vec(),
            data: b"payload".to_vec(),
            raw_data: None,
            raw_attrs: None,
            attrs: 0,
            handle,
        });
        loaded.cpu.gpr[3] = handle;
        loaded.cpu.gpr[4] = 101;
        loaded.cpu.gpr[5] = scratch;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);
        assert_eq!(loaded.vfs_resources[0].res_id, 101);
        assert_eq!(loaded.vfs_resources[0].name, b"NewName");

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::SetResAttrs;
        loaded.cpu.gpr[3] = handle;
        loaded.cpu.gpr[4] = u32::from(PPC_RES_PROTECTED_ATTR | PPC_RES_CHANGED_ATTR);

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);
        assert_eq!(
            loaded.vfs_resources[0].attrs,
            PPC_RES_PROTECTED_ATTR | PPC_RES_CHANGED_ATTR
        );

        write_ppc_pstring(&mut loaded.memory, scratch, b"Blocked");
        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::SetResInfo;
        loaded.cpu.gpr[3] = handle;
        loaded.cpu.gpr[4] = 102;
        loaded.cpu.gpr[5] = scratch;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.handled_import_count, 1);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_RES_ATTR_ERR);
        assert_eq!(loaded.vfs_resources[0].res_id, 101);
        assert_eq!(loaded.vfs_resources[0].name, b"NewName");
    }

    #[test]
    fn named_resource_lookups_follow_current_map_and_case_insensitive_names() {
        let pef = synthetic_pef_with_import(b"GetNamedResource");
        let mut loaded = load_pef_application(&pef).unwrap();
        let name_ptr = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(name_ptr, vec![0; 256]);
        write_ppc_pstring(&mut loaded.memory, name_ptr, b"Splash");
        let res_type = u32::from_be_bytes(*b"DATA");
        loaded.vfs_resources.extend([
            PpcVfsResourceRecord {
                ref_num: 7,
                path: "Earlier".to_string(),
                res_type,
                res_id: 100,
                name: b"Splash".to_vec(),
                data: b"earlier".to_vec(),
                raw_data: None,
                raw_attrs: None,
                attrs: 0,
                handle: 0,
            },
            PpcVfsResourceRecord {
                ref_num: 9,
                path: "Current".to_string(),
                res_type,
                res_id: 101,
                name: b"sPLASH".to_vec(),
                data: b"current".to_vec(),
                raw_data: None,
                raw_attrs: None,
                attrs: 0,
                handle: 0,
            },
        ]);
        loaded.current_resource_refnum = 9;
        loaded.cpu.gpr[3] = res_type;
        loaded.cpu.gpr[4] = name_ptr;

        let probe = loaded.run_with_hle_imports(64);

        assert_eq!(probe.unsupported_import_index, None);
        let handle = loaded.cpu.gpr[3];
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);
        assert_eq!(
            ppc_handle_bytes(&mut loaded.memory, &loaded.handles, handle),
            Some(b"current".to_vec())
        );

        write_ppc_pstring(&mut loaded.memory, name_ptr, b"Missing");
        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::Get1NamedResource;
        loaded.cpu.gpr[3] = res_type;
        loaded.cpu.gpr[4] = name_ptr;
        let probe = loaded.run_with_hle_imports(64);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.cpu.gpr[3], 0);
        assert_eq!(loaded.last_resource_error, PPC_RES_NOT_FOUND_ERR);
    }

    #[test]
    fn read_partial_resource_streams_empty_handles_and_reports_loaded_handles() {
        let pef = synthetic_pef_with_import(b"GetResource");
        let mut loaded = load_pef_application(&pef).unwrap();
        let buffer = PPC_DATA_BASE + 0x1000;
        loaded.memory.add_region(buffer, vec![0; 16]);
        loaded.resource_load_enabled = false;
        loaded.vfs_resources.push(PpcVfsResourceRecord {
            ref_num: loaded.current_resource_refnum,
            path: "Game".to_string(),
            res_type: u32::from_be_bytes(*b"DATA"),
            res_id: 128,
            name: Vec::new(),
            data: b"abcdefgh".to_vec(),
            raw_data: None,
            raw_attrs: None,
            attrs: 0,
            handle: 0,
        });
        loaded.cpu.gpr[3] = u32::from_be_bytes(*b"DATA");
        loaded.cpu.gpr[4] = 128;
        loaded.run_with_hle_imports(64);
        let handle = loaded.cpu.gpr[3];
        assert_ne!(handle, 0);
        assert_eq!(loaded.memory.read_u32_be(handle), Some(0));

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::ReadPartialResource;
        loaded.cpu.gpr[3] = handle;
        loaded.cpu.gpr[4] = 2;
        loaded.cpu.gpr[5] = buffer;
        loaded.cpu.gpr[6] = 4;
        let probe = loaded.run_with_hle_imports(64);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, buffer, 4),
            Some(b"cdef".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::LoadResource;
        loaded.cpu.gpr[3] = handle;
        loaded.run_with_hle_imports(64);
        assert_ne!(loaded.memory.read_u32_be(handle), Some(0));

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::ReadPartialResource;
        loaded.cpu.gpr[3] = handle;
        loaded.cpu.gpr[4] = 0;
        loaded.cpu.gpr[5] = buffer + 8;
        loaded.cpu.gpr[6] = 2;
        loaded.run_with_hle_imports(64);
        assert_eq!(loaded.last_resource_error, PPC_RESOURCE_IN_MEMORY_ERR);
        assert_eq!(
            ppc_memory_read_bytes(&mut loaded.memory, buffer + 8, 2),
            Some(b"ab".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.gpr[4] = 7;
        loaded.cpu.gpr[6] = 2;
        loaded.run_with_hle_imports(64);
        assert_eq!(loaded.last_resource_error, PPC_INPUT_OUT_OF_BOUNDS_ERR);
    }

    #[test]
    fn classic_resource_convenience_calls_and_hcreate_use_the_vfs() {
        let pef = synthetic_pef_with_import(b"GetIcon");
        let mut loaded = load_pef_application(&pef).unwrap();
        for (res_type, res_id, data) in [
            (*b"ICON", 128, b"icon".as_slice()),
            (*b"PAT ", 129, b"pattern".as_slice()),
        ] {
            loaded.vfs_resources.push(PpcVfsResourceRecord {
                ref_num: loaded.current_resource_refnum,
                path: "Game".to_string(),
                res_type: u32::from_be_bytes(res_type),
                res_id,
                name: Vec::new(),
                data: data.to_vec(),
                raw_data: None,
                raw_attrs: None,
                attrs: 0,
                handle: 0,
            });
        }
        loaded.cpu.gpr[3] = 128;
        loaded.run_with_hle_imports(64);
        assert_eq!(
            ppc_handle_bytes(&mut loaded.memory, &loaded.handles, loaded.cpu.gpr[3]),
            Some(b"icon".to_vec())
        );

        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::GetPattern;
        loaded.cpu.gpr[3] = 129;
        loaded.run_with_hle_imports(64);
        assert_eq!(
            ppc_handle_bytes(&mut loaded.memory, &loaded.handles, loaded.cpu.gpr[3]),
            Some(b"pattern".to_vec())
        );

        let name_ptr = PPC_DATA_BASE + 0x1100;
        loaded.memory.add_region(name_ptr, vec![0; 256]);
        write_ppc_pstring(&mut loaded.memory, name_ptr, b"Preferences");
        loaded.cpu.pc = loaded.entry_pc;
        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::HCreateResFile;
        loaded.cpu.gpr[3] = PPC_BOOT_VOLUME_REF_NUM as u16 as u32;
        loaded.cpu.gpr[4] = PPC_ROOT_DIR_ID;
        loaded.cpu.gpr[5] = name_ptr;
        let probe = loaded.run_with_hle_imports(64);
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.last_resource_error, PPC_NO_ERR);
        assert_eq!(loaded.vfs_files[0].path, "Preferences");
        assert_eq!(loaded.vfs_resource_files[0].path, "Preferences");
        assert!(loaded.vfs_resource_files[0].dirty);
    }

    #[test]
    fn game_managed_dialogs_require_visible_user_items_only() {
        let bounds = (100, 100, 300, 500);
        let user_item = |item_type, rect| PpcDialogItemView {
            item_offset: 0,
            item_type,
            rect,
            handle: 0,
            payload: Vec::new(),
        };
        let user_items = [
            user_item(PPC_DIALOG_ITEM_USER_ITEM, (0, 0, 20, 20)),
            user_item(
                PPC_DIALOG_ITEM_USER_ITEM | PPC_DIALOG_ITEM_DISABLED,
                (30, 30, 50, 50),
            ),
            user_item(PPC_DIALOG_ITEM_BUTTON, (0, 0x4000, 20, 0x4010)),
        ];

        assert!(ppc_dialog_is_game_managed(bounds, &user_items));

        let mut standard_items = user_items.to_vec();
        standard_items.push(user_item(PPC_DIALOG_ITEM_BUTTON, (60, 60, 80, 140)));
        assert!(!ppc_dialog_is_game_managed(bounds, &standard_items));
    }

    #[test]
    fn draw_dialog_calls_native_user_item_procedure_with_dialog_and_item_number() {
        let pef = synthetic_pef_with_import(b"GetNewDialog");
        let mut loaded = load_pef_application(&pef).unwrap();
        let mut dlog = vec![0; 22];
        dlog[4..6].copy_from_slice(&100i16.to_be_bytes());
        dlog[6..8].copy_from_slice(&200i16.to_be_bytes());
        dlog[10] = 1;
        dlog[18..20].copy_from_slice(&128i16.to_be_bytes());
        let mut ditl = vec![0; 16];
        ditl[6..8].copy_from_slice(&10i16.to_be_bytes());
        ditl[8..10].copy_from_slice(&12i16.to_be_bytes());
        ditl[10..12].copy_from_slice(&40i16.to_be_bytes());
        ditl[12..14].copy_from_slice(&80i16.to_be_bytes());
        ditl[14] = PPC_DIALOG_ITEM_USER_ITEM;
        for (res_type, data) in [(*b"DLOG", dlog), (*b"DITL", ditl)] {
            loaded.vfs_resources.push(PpcVfsResourceRecord {
                ref_num: loaded.current_resource_refnum,
                path: String::new(),
                res_type: u32::from_be_bytes(res_type),
                res_id: 128,
                name: Vec::new(),
                data,
                raw_data: None,
                raw_attrs: None,
                attrs: 0,
                handle: 0,
            });
        }
        loaded.cpu.gpr[3] = 128;
        loaded.run_with_hle_imports(64);
        let dialog = loaded.cpu.gpr[3];
        let items_handle = loaded
            .memory
            .read_u32_be(dialog + PPC_DIALOG_ITEMS_OFFSET)
            .unwrap();
        let items_ptr = loaded.memory.read_u32_be(items_handle).unwrap();
        let callback = PPC_CODE_BASE + 0x1000;
        let result = PPC_DATA_BASE + 0x1000;
        let mut callback_code = Vec::new();
        for word in [
            d_form_u(15, 5, 0, (result >> 16) as u16), // lis r5, result@h
            d_form_u(24, 5, 5, result as u16),         // ori r5, r5, result@l
            d_form_u(36, 3, 5, 0),                     // stw r3, 0(r5)
            d_form_u(36, 4, 5, 4),                     // stw r4, 4(r5)
            BLR,
        ] {
            callback_code.extend_from_slice(&word.to_be_bytes());
        }
        loaded.memory.add_region(callback, callback_code);
        loaded.memory.add_region(result, vec![0; 8]);
        loaded.memory.write_u32_be(items_ptr + 2, callback).unwrap();

        loaded.imports[0].dispatcher_target = PpcImportDispatcherTarget::DrawDialog;
        loaded.cpu.pc = loaded.entry_pc;
        loaded.cpu.lr = PPC_HALT_PC;
        loaded.cpu.gpr[3] = dialog;
        loaded.current_gworld = PPC_MAIN_GWORLD;
        let probe = loaded.run_with_hle_imports(128);

        assert!(matches!(probe.result, PpcRunResult::Halted { .. }));
        assert_eq!(probe.unsupported_import_index, None);
        assert_eq!(loaded.memory.read_u32_be(result), Some(dialog));
        assert_eq!(loaded.memory.read_u32_be(result + 4), Some(1));
        assert_eq!(loaded.current_gworld, dialog);
        assert!(loaded.dialog_callback_stack.is_empty());
    }

